import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FiClock, FiHeart } from 'react-icons/fi';
import { blog } from '../services/api';
import Header from '../components/Header';
import Footer from '../components/Footer';

const BlogList = () => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        const res = await blog.getAll({ page, limit: 12 });
        setPosts(res.data.data || []);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchPosts();
  }, [page]);

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <main style={{ flex: 1 }}>
        <div className="container page-wrapper">
          <h1 style={{ fontSize: '22px', fontWeight: 700, marginBottom: '8px' }}>OptiKart Blog</h1>
          <p style={{ fontSize: '14px', color: 'var(--text-light)', marginBottom: '24px' }}>Eye care tips, style guides, and latest trends</p>

          {loading ? (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="card skeleton" style={{ height: '320px' }} />
              ))}
            </div>
          ) : posts.length === 0 ? (
            <div className="empty-state"><h3>No blog posts yet</h3><p>Check back soon for articles on eye care and eyewear trends</p></div>
          ) : (
            <>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                {posts.map((post) => (
                  <Link key={post._id} to={`/blog/${post.slug}`} className="card" style={{ overflow: 'hidden', transition: 'box-shadow 0.2s' }}>
                    <img src={post.coverImage || '/placeholder-blog.jpg'} alt={post.title} style={{ width: '100%', height: '180px', objectFit: 'cover' }} />
                    <div style={{ padding: '16px' }}>
                      <span className="badge badge-primary" style={{ marginBottom: '8px' }}>{post.category}</span>
                      <h3 style={{ fontSize: '16px', fontWeight: 600, marginBottom: '8px', lineHeight: 1.4 }} className="line-clamp-2">{post.title}</h3>
                      <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '12px' }} className="line-clamp-2">{post.excerpt}</p>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '12px', color: 'var(--text-light)' }}>
                        <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}><FiClock size={12} /> {new Date(post.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                        <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}><FiHeart size={12} /> {post.likes || 0}</span>
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
              <div style={{ display: 'flex', justifyContent: 'center', gap: '8px', marginTop: '32px' }}>
                <button onClick={() => setPage(Math.max(1, page - 1))} disabled={page === 1} className="btn btn-outline btn-sm">Previous</button>
                <span style={{ padding: '6px 12px', fontSize: '14px' }}>Page {page}</span>
                <button onClick={() => setPage(page + 1)} className="btn btn-outline btn-sm">Next</button>
              </div>
            </>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default BlogList;
